module right_shifter(
    input clk, input d,
    output reg [7:0] q
);
    parameter state_0 = 0;
    parameter state_1 = 1;
    reg [1:0] state;
    always @(posedge clk) begin
        case (state)
            state_0: begin
                q <= 8'b00000000;
                state <= state_1;
            end
            state_1: begin
                q <= (q >> 1);
                q[7] <= d;
                state <= state_1;
            end
        endcase
    end
endmodule
